static int mdTextW(const char *s)
{
  int w = 0;
  for (; *s; s++)
    if (*s >= 32 && *s < 127)
      w += MD_GLYPHS[*s - 32].adv;
  return w;
}

static void mdPrint(int x, int y, const char *s, uint16_t col)
{
  for (; *s; s++)
  {
    if (*s < 32 || *s >= 127)
      continue;
    const MDGlyph &g = MD_GLYPHS[*s - 32];
    int stride = (g.w + 7) / 8;
    for (int gy = 0; gy < MD_H; gy++)
      for (int gx = 0; gx < g.w; gx++)
        if (MD_BITS[g.off + gy * stride + gx / 8] & (0x80 >> (gx & 7)))
          canvas->drawPixel(x + g.xoff + gx, y + gy, col);
    x += g.adv;
  }
}
